//! Independently authored 3MF fixture suite (issue #20).
//!
//! Every fixture is generated by [`catalog`] below and checked into
//! `tests/fixtures/threemf/` together with `manifest.json`, which records each
//! file's SHA-256 and its expected parse outcome. The tests here:
//!
//! * verify the checked-in bytes still match the recorded digest (provenance —
//!   a fixture cannot be silently edited);
//! * verify the reader's observable behaviour against the manifest, for both
//!   the well-formed and the deliberately hostile/corrupt cases.
//!
//! Regenerate after intentionally changing a fixture:
//!
//! ```text
//! cargo test --manifest-path native/Cargo.toml -p model-core \
//!     --test threemf_fixtures -- --ignored regenerate_threemf_fixtures
//! ```

mod threemf_support;

use std::collections::BTreeSet;
use std::fs;
use std::path::PathBuf;

use model_core::threemf;
use model_core::vendor;
use serde::{Deserialize, Serialize};

use threemf_support::{
    box_object, model_document, package, sha256_hex, tiny_png, triangle_object, zip_parts,
    CONTENT_TYPES_PART, CONTENT_TYPES_XML, DEFAULT_MODEL_PART, RELATIONSHIPS_PART, RELS_XML,
};

#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct FixtureManifest {
    /// How to reproduce every file listed below.
    generator: String,
    provenance: String,
    fixtures: Vec<FixtureRecord>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct FixtureRecord {
    file: String,
    label: String,
    notes: String,
    sha256: String,
    byte_len: usize,
    #[serde(skip_serializing_if = "Option::is_none")]
    expected: Option<ExpectedScene>,
    #[serde(skip_serializing_if = "Option::is_none")]
    expected_vendor: Option<ExpectedVendor>,
    /// Stable [`threemf::ThreeMfError::code`] for fixtures that must be
    /// rejected. Mutually exclusive with `expected`.
    #[serde(skip_serializing_if = "Option::is_none")]
    expected_error: Option<String>,
}

#[derive(Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ExpectedScene {
    unit: String,
    vertex_count: usize,
    triangle_count: usize,
    object_count: usize,
    build_item_count: usize,
    part_count: usize,
    part_names: Vec<String>,
    scene_object_count: usize,
    root_object_ids: Vec<String>,
    plate_count: usize,
    bounds_min: [f32; 3],
    bounds_max: [f32; 3],
}

#[derive(Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ExpectedVendor {
    slicer: String,
    plate_count: usize,
    plate_indices: Vec<u32>,
    filament_types: Vec<String>,
    thumbnail_parts: Vec<String>,
}

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("threemf")
}

fn read_manifest() -> FixtureManifest {
    let path = fixture_dir().join("manifest.json");
    serde_json::from_slice(&fs::read(&path).expect("read 3MF fixture manifest"))
        .expect("parse 3MF fixture manifest")
}

// --- fixture authoring -----------------------------------------------------

/// One authored fixture: the file name, human context, and raw package bytes.
struct Authored {
    file: &'static str,
    label: &'static str,
    notes: &'static str,
    bytes: Vec<u8>,
}

/// Every fixture, authored from first principles rather than captured from a
/// slicer, so the expectations can be derived by hand.
fn catalog() -> Vec<Authored> {
    vec![
        multi_part(),
        transform_chain(),
        color_material(),
        multi_plate(),
        unit_inch(),
        large_grid(),
        malformed_not_a_zip(),
        malformed_missing_model(),
        malformed_triangle_index(),
        malformed_component_cycle(),
        malformed_nan_vertex(),
        malformed_doctype_entity(),
        malformed_external_entity(),
        malformed_deep_nesting(),
        malformed_zip_bomb(),
        malformed_path_traversal(),
    ]
}

fn multi_part() -> Authored {
    let resources = [
        box_object("1", "Bracket", [10.0, 20.0, 5.0], ""),
        box_object("2", "Spacer", [4.0, 4.0, 4.0], ""),
        box_object("3", "Cap", [6.0, 6.0, 2.0], ""),
    ]
    .join("\n");
    let build = r#"    <item objectid="1"/>
    <item objectid="2" transform="1 0 0 0 1 0 0 0 1 20 0 0"/>
    <item objectid="3" transform="1 0 0 0 1 0 0 0 1 0 30 0"/>"#;
    Authored {
        file: "multi_part.3mf",
        label: "multi-part",
        notes: "Three independently named box objects, each placed once by the build.",
        bytes: package(&model_document("millimeter", &resources, build), Vec::new()),
    }
}

fn transform_chain() -> Authored {
    // Object 3 is a component assembly that instances the same box twice under
    // different local transforms; the build item adds a third transform on top,
    // so the fixture pins the whole composition chain.
    let resources = format!(
        "{}\n{}",
        box_object("1", "Unit", [2.0, 2.0, 2.0], ""),
        r#"    <object id="3" name="Assembly" type="model">
      <components>
        <component objectid="1"/>
        <component objectid="1" transform="2 0 0 0 2 0 0 0 2 10 0 0"/>
      </components>
    </object>"#
    );
    let build = r#"    <item objectid="3" transform="0 1 0 -1 0 0 0 0 1 100 50 0"/>"#;
    Authored {
        file: "transform_chain.3mf",
        label: "transform",
        notes:
            "Nested components with scale/translate composed under a rotating build-item transform.",
        bytes: package(&model_document("millimeter", &resources, build), Vec::new()),
    }
}

fn color_material() -> Authored {
    // Material and color resources plus per-object and per-triangle property
    // references. The core reader does not surface appearance yet; this fixture
    // pins that they parse cleanly and never perturb geometry.
    let resources = format!(
        r##"    <basematerials id="10">
      <base name="PLA Red" displaycolor="#FF0000FF"/>
      <base name="PLA Blue" displaycolor="#0000FFFF"/>
    </basematerials>
    <m:colorgroup xmlns:m="http://schemas.microsoft.com/3dmanufacturing/material/2015/02" id="11">
      <m:color color="#12AB34FF"/>
      <m:color color="#FFCC00FF"/>
    </m:colorgroup>
{}
{}"##,
        box_object("1", "Red body", [8.0, 8.0, 8.0], r#" pid="10" pindex="0""#),
        triangle_object_with_properties("2", "Painted fin"),
    );
    let build = r#"    <item objectid="1"/>
    <item objectid="2" transform="1 0 0 0 1 0 0 0 1 0 0 20"/>"#;
    Authored {
        file: "color_material.3mf",
        label: "color + material",
        notes: "basematerials, a material-extension colorgroup, object-level pid/pindex and per-triangle p1/p2/p3.",
        bytes: package(&model_document("millimeter", &resources, build), Vec::new()),
    }
}

fn triangle_object_with_properties(id: &str, name: &str) -> String {
    format!(
        r#"    <object id="{id}" name="{name}" type="model" pid="11" pindex="1">
      <mesh>
        <vertices>
          <vertex x="0" y="0" z="0"/>
          <vertex x="5" y="0" z="0"/>
          <vertex x="0" y="5" z="0"/>
          <vertex x="0" y="0" z="5"/>
        </vertices>
        <triangles>
          <triangle v1="0" v2="1" v3="2" pid="11" p1="0" p2="1" p3="0"/>
          <triangle v1="0" v2="1" v3="3" pid="11" p1="1"/>
          <triangle v1="1" v2="2" v3="3"/>
          <triangle v1="0" v2="3" v3="2"/>
        </triangles>
      </mesh>
    </object>"#
    )
}

fn multi_plate() -> Authored {
    let resources = [
        box_object("1", "Plate one body", [10.0, 10.0, 10.0], ""),
        box_object("2", "Plate two body", [6.0, 6.0, 6.0], ""),
    ]
    .join("\n");
    let build = r#"    <item objectid="1"/>
    <item objectid="2" transform="1 0 0 0 1 0 0 0 1 40 0 0"/>"#;
    let model = model_document("millimeter", &resources, build);
    let slice_info = r#"<?xml version="1.0" encoding="UTF-8"?>
<config>
  <header/>
  <plate>
    <metadata key="index" value="1"/>
    <metadata key="prediction" value="3600"/>
    <metadata key="weight" value="24.5"/>
    <filament id="1" type="PLA" used_g="24.5"/>
  </plate>
  <plate>
    <metadata key="index" value="2"/>
    <metadata key="prediction" value="1800"/>
    <metadata key="weight" value="8.25"/>
    <filament id="1" type="PETG" used_g="8.25"/>
  </plate>
</config>"#;
    let png = tiny_png();
    Authored {
        file: "multi_plate.3mf",
        label: "multi-plate",
        notes: "Bambu/Orca-style slice_info.config describing two plates plus one PNG thumbnail per plate.",
        bytes: package(
            &model,
            vec![
                threemf_support::Part::text("Metadata/slice_info.config", slice_info),
                threemf_support::Part::bytes("Metadata/plate_1.png", png.clone()),
                threemf_support::Part::bytes("Metadata/plate_2.png", png),
            ],
        ),
    }
}

fn unit_inch() -> Authored {
    let resources = box_object("1", "Inch cube", [1.0, 2.0, 0.5], "");
    let build = r#"    <item objectid="1"/>"#;
    Authored {
        file: "unit_inch.3mf",
        label: "unit declaration",
        notes: "Root model declared in inches; the reader reports the declared unit and preserves model-space coordinates (only external model parts are rescaled to the root unit).",
        bytes: package(&model_document("inch", &resources, build), Vec::new()),
    }
}

fn large_grid() -> Authored {
    // 40x40 quads => 1681 vertices / 3200 triangles: large enough to exercise
    // the per-vertex work budget, small enough to stay a tidy repo artifact.
    const N: usize = 40;
    let mut vertices = String::new();
    for row in 0..=N {
        for col in 0..=N {
            vertices.push_str(&format!(
                "          <vertex x=\"{}\" y=\"{}\" z=\"0\"/>\n",
                col as f32, row as f32
            ));
        }
    }
    let mut triangles = String::new();
    for row in 0..N {
        for col in 0..N {
            let a = row * (N + 1) + col;
            let b = a + 1;
            let c = a + N + 1;
            let d = c + 1;
            triangles.push_str(&format!(
                "          <triangle v1=\"{a}\" v2=\"{b}\" v3=\"{d}\"/>\n          <triangle v1=\"{a}\" v2=\"{d}\" v3=\"{c}\"/>\n"
            ));
        }
    }
    let resources = format!(
        r#"    <object id="1" name="Grid" type="model">
      <mesh>
        <vertices>
{vertices}        </vertices>
        <triangles>
{triangles}        </triangles>
      </mesh>
    </object>"#
    );
    let build = r#"    <item objectid="1"/>"#;
    Authored {
        file: "large_grid.3mf",
        label: "large",
        notes: "40x40 triangulated grid (1681 vertices / 3200 triangles).",
        bytes: package(&model_document("millimeter", &resources, build), Vec::new()),
    }
}

fn malformed_not_a_zip() -> Authored {
    Authored {
        file: "malformed_not_a_zip.3mf",
        label: "malformed: not an archive",
        notes: "Plain text with a .3mf extension; must be rejected before any ZIP reader work, not panic.",
        bytes: b"this is not a 3MF package, it is just some bytes\n".to_vec(),
    }
}

fn malformed_missing_model() -> Authored {
    Authored {
        file: "malformed_missing_model.3mf",
        label: "malformed: no model part",
        notes:
            "Valid OPC container whose relationships point at a part that is not in the archive.",
        bytes: zip_parts(&[
            threemf_support::Part::text(CONTENT_TYPES_PART, CONTENT_TYPES_XML),
            threemf_support::Part::text(RELATIONSHIPS_PART, RELS_XML),
            threemf_support::Part::text("Metadata/readme.config", "<config/>"),
        ]),
    }
}

