fn malformed_nan_vertex() -> Authored {
    let resources = r#"    <object id="1" name="Poisoned" type="model">
      <mesh>
        <vertices>
          <vertex x="0" y="0" z="0"/>
          <vertex x="NaN" y="0" z="0"/>
          <vertex x="0" y="Infinity" z="0"/>
        </vertices>
        <triangles>
          <triangle v1="0" v2="1" v3="2"/>
        </triangles>
      </mesh>
    </object>"#;
    let build = r#"    <item objectid="1"/>"#;
    Authored {
        file: "malformed_nan_vertex.3mf",
        label: "malformed: non-finite coordinates",
        notes:
            "NaN/Infinity vertex coordinates would poison the bounds and serialize as JSON null.",
        bytes: package(&model_document("millimeter", resources, build), Vec::new()),
    }
}

fn malformed_doctype_entity() -> Authored {
    // Classic "billion laughs": nine levels of entity expansion. The reader
    // must refuse the DOCTYPE outright rather than expanding anything.
    let model = r#"<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE model [
  <!ENTITY lol "lol">
  <!ENTITY lol1 "&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;">
  <!ENTITY lol2 "&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;&lol1;">
  <!ENTITY lol3 "&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;">
  <!ENTITY lol4 "&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;">
  <!ENTITY lol5 "&lol4;&lol4;&lol4;&lol4;&lol4;&lol4;&lol4;&lol4;&lol4;&lol4;">
  <!ENTITY lol6 "&lol5;&lol5;&lol5;&lol5;&lol5;&lol5;&lol5;&lol5;&lol5;&lol5;">
  <!ENTITY lol7 "&lol6;&lol6;&lol6;&lol6;&lol6;&lol6;&lol6;&lol6;&lol6;&lol6;">
  <!ENTITY lol8 "&lol7;&lol7;&lol7;&lol7;&lol7;&lol7;&lol7;&lol7;&lol7;&lol7;">
  <!ENTITY lol9 "&lol8;&lol8;&lol8;&lol8;&lol8;&lol8;&lol8;&lol8;&lol8;&lol8;">
]>
<model unit="millimeter" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02">
  <metadata name="Title">&lol9;</metadata>
  <resources>
    <object id="1" type="model">
      <mesh>
        <vertices>
          <vertex x="0" y="0" z="0"/>
          <vertex x="1" y="0" z="0"/>
          <vertex x="0" y="1" z="0"/>
        </vertices>
        <triangles><triangle v1="0" v2="1" v3="2"/></triangles>
      </mesh>
    </object>
  </resources>
  <build><item objectid="1"/></build>
</model>"#;
    Authored {
        file: "malformed_doctype_entity.3mf",
        label: "hostile: billion laughs",
        notes: "Recursive internal entity expansion inside a DOCTYPE.",
        bytes: package(model, Vec::new()),
    }
}

fn malformed_external_entity() -> Authored {
    let model = r#"<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE model [
  <!ENTITY xxe SYSTEM "file:///etc/passwd">
]>
<model unit="millimeter" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02">
  <metadata name="Designer">&xxe;</metadata>
  <resources>
    <object id="1" type="model">
      <mesh>
        <vertices>
          <vertex x="0" y="0" z="0"/>
          <vertex x="1" y="0" z="0"/>
          <vertex x="0" y="1" z="0"/>
        </vertices>
        <triangles><triangle v1="0" v2="1" v3="2"/></triangles>
      </mesh>
    </object>
  </resources>
  <build><item objectid="1"/></build>
</model>"#;
    Authored {
        file: "malformed_external_entity.3mf",
        label: "hostile: XXE",
        notes: "External SYSTEM entity attempting local file disclosure.",
        bytes: package(model, Vec::new()),
    }
}

fn malformed_deep_nesting() -> Authored {
    // Well below any byte ceiling, but far past the nesting limit: a parser
    // that recursed per element would blow its stack here.
    let depth = 5_000;
    let mut model = String::from(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<model unit="millimeter" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02">
  <resources>
"#,
    );
    for _ in 0..depth {
        model.push_str("<wrap>");
    }
    model.push_str("<object id=\"1\" type=\"model\"/>");
    for _ in 0..depth {
        model.push_str("</wrap>");
    }
    model.push_str("\n  </resources>\n  <build/>\n</model>");
    Authored {
        file: "malformed_deep_nesting.3mf",
        label: "hostile: XML depth",
        notes: "5,000 levels of nested elements inside <resources>.",
        bytes: package(&model, Vec::new()),
    }
}

fn malformed_zip_bomb() -> Authored {
    // 8 MiB of zeros deflates to a few KB: comfortably over both the ratio
    // limit and the small-entry floor that exempts ordinary tiny XML parts.
    let bomb = vec![0u8; 8 * 1024 * 1024];
    let resources = triangle_object("1", "Decoy");
    let build = r#"    <item objectid="1"/>"#;
    Authored {
        file: "malformed_zip_bomb.3mf",
        label: "hostile: decompression bomb",
        notes: "An 8 MiB all-zero thumbnail part with a ~1000:1 compression ratio.",
        bytes: package(
            &model_document("millimeter", &resources, build),
            vec![threemf_support::Part::bytes("Metadata/plate_1.png", bomb)],
        ),
    }
}

fn malformed_path_traversal() -> Authored {
    let resources = triangle_object("1", "Decoy");
    let build = r#"    <item objectid="1"/>"#;
    let model = model_document("millimeter", &resources, build);
    Authored {
        file: "malformed_path_traversal.3mf",
        label: "hostile: path traversal",
        notes:
            "An archive entry named ../../evil.txt, which must never be treated as a package part.",
        bytes: zip_parts(&[
            threemf_support::Part::text(CONTENT_TYPES_PART, CONTENT_TYPES_XML),
            threemf_support::Part::text(RELATIONSHIPS_PART, RELS_XML),
            threemf_support::Part::text(DEFAULT_MODEL_PART, &model),
            threemf_support::Part::text("../../evil.txt", "owned"),
        ]),
    }
}

// --- tests -----------------------------------------------------------------

#[test]
fn every_authored_fixture_is_checked_in_with_a_matching_digest() {
    let manifest = read_manifest();
    let recorded: BTreeSet<&str> = manifest.fixtures.iter().map(|f| f.file.as_str()).collect();
    let authored: BTreeSet<&str> = catalog().iter().map(|f| f.file).collect();
    assert_eq!(
        recorded, authored,
        "manifest.json and the fixture catalog disagree; regenerate the fixtures"
    );

    for record in &manifest.fixtures {
        let bytes = fs::read(fixture_dir().join(&record.file))
            .unwrap_or_else(|e| panic!("read fixture {}: {e}", record.file));
        assert_eq!(
            bytes.len(),
            record.byte_len,
            "{} changed size on disk",
            record.file
        );
        assert_eq!(
            sha256_hex(&bytes),
            record.sha256,
            "{} does not match its recorded digest",
            record.file
        );
    }
}

#[test]
fn well_formed_fixtures_match_their_expected_scenes() {
    for record in read_manifest().fixtures {
        let Some(expected) = record.expected else {
            continue;
        };
        let bytes = fs::read(fixture_dir().join(&record.file)).expect("read fixture");
        let mesh = threemf::parse_bytes(&bytes)
            .unwrap_or_else(|e| panic!("{} ({}) failed to parse: {e}", record.file, record.label));

        let actual = ExpectedScene {
            unit: mesh.unit.clone(),
            vertex_count: mesh.vertex_count(),
            triangle_count: mesh.triangle_count(),
            object_count: mesh.object_count,
            build_item_count: mesh.build_item_count,
            part_count: mesh.parts.len(),
            part_names: mesh.parts.iter().map(|p| p.name.clone()).collect(),
            scene_object_count: mesh.objects.len(),
            root_object_ids: mesh.root_object_ids.clone(),
            plate_count: mesh.plates.len(),
            bounds_min: mesh.bounds.min,
            bounds_max: mesh.bounds.max,
        };
        assert_eq!(actual, expected, "{} ({})", record.file, record.label);

        assert!(
            mesh.vertices.iter().flatten().all(|c| c.is_finite()),
            "{} produced a non-finite coordinate",
            record.file
        );
        for triangle in &mesh.triangles {
            for index in triangle {
                assert!(
                    (*index as usize) < mesh.vertices.len(),
                    "{} produced an out-of-range triangle index",
                    record.file
                );
            }
        }
    }
}

#[test]
fn rejected_fixtures_fail_with_their_expected_error_code() {
    for record in read_manifest().fixtures {
        let Some(expected_code) = record.expected_error else {
            continue;
        };
        let bytes = fs::read(fixture_dir().join(&record.file)).expect("read fixture");
        match threemf::parse_bytes(&bytes) {
            Ok(_) => panic!(
                "{} ({}) parsed but must be rejected",
                record.file, record.label
            ),
            Err(error) => assert_eq!(
                error.code(),
                expected_code,
                "{} ({}) failed with the wrong code: {error}",
                record.file,
                record.label
            ),
        }
    }
}

#[test]
fn vendor_fixtures_match_their_expected_metadata() {
    for record in read_manifest().fixtures {
        let Some(expected) = record.expected_vendor else {
            continue;
        };
        let bytes = fs::read(fixture_dir().join(&record.file)).expect("read fixture");
        let metadata = vendor::extract_bytes(&bytes)
            .unwrap_or_else(|e| panic!("{} vendor extraction failed: {e}", record.file));

        let actual = ExpectedVendor {
            slicer: format!("{:?}", metadata.slicer),
            plate_count: metadata.plates.len(),
            plate_indices: metadata.plates.iter().filter_map(|p| p.index).collect(),
            filament_types: metadata
                .plates
                .iter()
                .flat_map(|p| p.filament_types.clone())
                .collect(),
            thumbnail_parts: metadata.parts.thumbnails.clone(),
        };
        assert_eq!(actual, expected, "{} ({})", record.file, record.label);

        let thumbnails = vendor::read_plate_thumbnails(&bytes)
            .unwrap_or_else(|e| panic!("{} thumbnail extraction failed: {e}", record.file));
        assert_eq!(
            thumbnails.len(),
            expected.thumbnail_parts.len(),
            "{} thumbnail count",
            record.file
        );
        for thumbnail in thumbnails {
            assert!(
                thumbnail.png_bytes.starts_with(&[0x89, b'P', b'N', b'G']),
                "{} thumbnail {} is not a PNG",
                record.file,
                thumbnail.part_name
            );
        }
    }
}

/// Rewrite every fixture file and refresh `manifest.json`.
///
/// Expected values are recomputed from the reader, so **review the manifest
/// diff**: this is the point at which a behaviour change becomes visible.
#[test]
#[ignore = "regenerates checked-in fixtures; run explicitly"]
fn regenerate_threemf_fixtures() {
    let dir = fixture_dir();
    fs::create_dir_all(&dir).expect("create fixture dir");

    let mut records = Vec::new();
    for authored in catalog() {
        fs::write(dir.join(authored.file), &authored.bytes).expect("write fixture");

        let parsed = threemf::parse_bytes(&authored.bytes);
        let (expected, expected_error) = match &parsed {
            Ok(mesh) => (
                Some(ExpectedScene {
                    unit: mesh.unit.clone(),
                    vertex_count: mesh.vertex_count(),
                    triangle_count: mesh.triangle_count(),
                    object_count: mesh.object_count,
                    build_item_count: mesh.build_item_count,
                    part_count: mesh.parts.len(),
                    part_names: mesh.parts.iter().map(|p| p.name.clone()).collect(),
                    scene_object_count: mesh.objects.len(),
                    root_object_ids: mesh.root_object_ids.clone(),
                    plate_count: mesh.plates.len(),
                    bounds_min: mesh.bounds.min,
                    bounds_max: mesh.bounds.max,
                }),
                None,
            ),
            Err(error) => (None, Some(error.code().to_string())),
        };

        let expected_vendor = if authored.file == "multi_plate.3mf" {
            let metadata = vendor::extract_bytes(&authored.bytes).expect("vendor metadata");
            Some(ExpectedVendor {
                slicer: format!("{:?}", metadata.slicer),
                plate_count: metadata.plates.len(),
                plate_indices: metadata.plates.iter().filter_map(|p| p.index).collect(),
                filament_types: metadata
                    .plates
                    .iter()
                    .flat_map(|p| p.filament_types.clone())
                    .collect(),
                thumbnail_parts: metadata.parts.thumbnails.clone(),
            })
        } else {
            None
        };

        records.push(FixtureRecord {
            file: authored.file.to_string(),
            label: authored.label.to_string(),
            notes: authored.notes.to_string(),
            sha256: sha256_hex(&authored.bytes),
            byte_len: authored.bytes.len(),
            expected,
            expected_vendor,
            expected_error,
        });
    }

    let manifest = FixtureManifest {
        generator: "cargo test --manifest-path native/Cargo.toml -p model-core --test threemf_fixtures -- --ignored regenerate_threemf_fixtures".to_string(),
        provenance: "Authored by hand for PrintFarmer issue #20; no third-party model data. Each package is assembled from raw OPC parts by tests/threemf_fixtures.rs.".to_string(),
        fixtures: records,
    };
    let mut json = serde_json::to_string_pretty(&manifest).expect("serialize manifest");
    json.push('\n');
    fs::write(dir.join("manifest.json"), json).expect("write manifest");
}
